
import { defineComponent } from 'vue';

import { SettingsEventEmitter } from '@game-studio/settings';

import MenuItem from './menu-item/menu-item.vue';

import { Injects } from '../../inversify/injects';
import { inversifyContainer } from '../../inversify/container';
import { useCompanionState } from '../../models/companion-state';
import { gameConfig } from '../../models/config-model';
import { device } from '../../services/device';
import { eventEmitter } from '../../services/event-emitter';
import { PrizeLeagueManager } from '../../services/prize-league/prize-league-manager';
import { queryStringParams } from '../../services/query-string';

export default defineComponent({
    name: 'ActionMenu',
    components: {
        MenuItem
    },
    props: {
    },
    data() {
        return {
            showGigIcon: gameConfig.features.enableGameInGame,
            showLobbyIcon: gameConfig.features.enableLobby,
            showPrizeLeagueIcon: gameConfig.features.enablePrizeLeague && queryStringParams.launchedFrom === 'arcade',
            showSettingsIcon: gameConfig.features.enableSettings,
            showChatIcon: gameConfig.features.enableChat,
            canGameInGame: true
        };
    },
    computed: {
        translations() {
            return inversifyContainer.strings.actionMenu;
        },
        // Show red dot when tournament results are ready (takes priority)
        showPrizeLeagueNotificationDot() {
            return this.state.isPrizeLeagueNotificationVisible.value && !this.state.isPrizeLeagueOpen.value;
        },
        // Show spin count badge when in active tournament with remaining spins (lower priority)
        prizeLeagueNotificationText() {
            // Don't show spin count if notification dot is showing (results ready takes priority)
            if (this.state.isPrizeLeagueNotificationVisible.value) {
                return '';
            }

            // Only show if prize league is enabled, panel is closed, and there's an active tournament
            if (!gameConfig.features.enablePrizeLeague || this.state.isPrizeLeagueOpen.value || !this.showPrizeLeagueIcon) {
                return '';
            }

            const prizeLeagueManager = inversifyContainer.get<PrizeLeagueManager>(Injects.PrizeLeagueManager);
            const activeTournament = prizeLeagueManager.activeTournament.value;

            // Only show if player is opted in and has remaining spins
            if (activeTournament && activeTournament.isOptedIn && activeTournament.spinsUsed < activeTournament.totalSpins) {
                return `${activeTournament.spinsUsed}/${activeTournament.totalSpins}`;
            }

            return '';
        }
    },
    setup() {
        const { menuHeight, isChatNotificationVisible, isGigNotificationVisible, isGameInGameOpen, isSubGameOpen, isChatOpen, isPrizeLeagueOpen, isPrizeLeagueNotificationVisible, hide, show } = useCompanionState();

        return {
            state: {
                height: menuHeight,
                isGameInGameOpen,
                isPrizeLeagueOpen,
                isSubGameOpen,
                isChatOpen,
                isChatNotificationVisible,
                isGigNotificationVisible,
                isPrizeLeagueNotificationVisible
            },
            hidePanel: hide,
            showPanel: show
        };
    },
    mounted(): void {
        if (device.type.isDesktop) {
            this.state.height.value = 55; 
        } else {
            this.state.height.value = device.orientation.isPortrait ? 55 : 0;
        }

        eventEmitter.on('SHOW_PRIZE_LEAGUE_RESULTS', this.onPrizeLeagueResultsReady);
    },
    unmounted(): void {
        eventEmitter.off('SHOW_PRIZE_LEAGUE_RESULTS', this.onPrizeLeagueResultsReady);
    },
    methods: {
        onOrientationChange(): void {
            this.state.height.value = device.orientation.isPortrait ? 55 : 0;
        },
        onPrizeLeagueResultsReady(): void {
            // Only show the notification dot if the prize league panel is not currently open
            if (!this.state.isPrizeLeagueOpen.value) {
                this.state.isPrizeLeagueNotificationVisible.value = true;
            }
        },
        onSplitScreenClick(): void {
            if (this.state.isGameInGameOpen.value) {
                this.hidePanel();
            } else {
                this.showPanel('gameInGame');
            }
        },
        onLobbyClick(): void {
            eventEmitter.emit('ACTION_MENU_LOBBY_CLICKED');
        },
        onPrizeLeagueClick(): void {
            this.state.isPrizeLeagueNotificationVisible.value = false;

            // On desktop, only open prize league (never close it)
            if (device.type.isDesktop) {
                if (!this.state.isPrizeLeagueOpen.value) {
                    this.showPanel('prizeLeague');
                }
            } else {
                // On mobile/tablet, toggle behavior
                if (this.state.isPrizeLeagueOpen.value) {
                    this.hidePanel();
                } else {
                    this.showPanel('prizeLeague');
                }
            }
        },
        onSettingsClick(): void {
            SettingsEventEmitter.emit('show');
        },
        onChatClick(): void {
            if (this.state.isChatNotificationVisible.value) {
                this.state.isChatNotificationVisible.value = false;
            }

            // On desktop, only open chat (never close it)
            if (device.type.isDesktop) {
                if (!this.state.isChatOpen.value) {
                    this.showPanel('chat');
                }
            } else {
                // On mobile/tablet, toggle behavior
                if (this.state.isChatOpen.value) {
                    this.hidePanel();
                } else {
                    this.showPanel('chat');
                }
            }
        }
    }
});